<div class="min-h-screen bg-neutral-50">
  <header class="sticky top-0 z-50 w-full bg-white/95 backdrop-blur border-b border-neutral-200">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between gap-4">
      <div class="flex items-center gap-3">
        <h1 class="text-xl font-bold text-neutral-900">پنل فروشنده</h1>
      </div>
      <div class="flex items-center gap-4">
        <button class="inline-flex items-center gap-2 bg-transparent text-neutral-600 font-medium text-base px-4 py-2.5 rounded-lg hover:bg-neutral-100 transition-all focus:outline-none focus:ring-2 focus:ring-neutral-400">
          <span>پنل اصلی</span>
        </button>
      </div>
    </div>
  </header>

  <main class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
    <div class="space-y-8">
      <div class="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
        {/* Summary Cards */}
        {summaryData ? (
          <>
            <motion.div
              variants={cardVariants}
              initial="hidden"
              animate="show"
              className="bg-white rounded-lg border border-neutral-200 shadow-sm overflow-hidden transition-all hover:shadow-md"
            >
              <div class="p-6">
                <h3 class="text-sm font-medium text-neutral-600 mb-2">مجموع فروش</h3>
                <p class="text-2xl font-bold text-neutral-900">
                  {formatCurrency(summaryData.totalSales)}
                </p>
              </div>
            </motion.div>

            <motion.div
              variants={cardVariants}
              initial="hidden"
              animate="show"
              className="bg-white rounded-lg border border-neutral-200 shadow-sm overflow-hidden transition-all hover:shadow-md"
            >
              <div class="p-6">
                <h3 class="text-sm font-medium text-neutral-600 mb-2">کمیسیون پرداختی</h3>
                <p class="text-2xl font-bold text-neutral-900">
                  {formatCurrency(summaryData.commissionPaid)}
                </p>
              </div>
            </motion.div>

            <motion.div
              variants={cardVariants}
              initial="hidden"
              animate="show"
              className="bg-white rounded-lg border border-neutral-200 shadow-sm overflow-hidden transition-all hover:shadow-md"
            >
              <div class="p-6">
                <h3 class="text-sm font-medium text-neutral-600 mb-2">مالیات</h3>
                <p class="text-2xl font-bold text-neutral-900">
                  {formatCurrency(summaryData.tax)}
                </p>
              </div>
            </motion.div>

            <motion.div
              variants={cardVariants}
              initial="hidden"
              animate="show"
              className="bg-white rounded-lg border border-neutral-200 shadow-sm overflow-hidden transition-all hover:shadow-md"
            >
              <div class="p-6">
                <h3 class="text-sm font-medium text-neutral-600 mb-2">قابل تسویه</h3>
                <p class="text-2xl font-bold text-neutral-900">
                  {formatCurrency(summaryData.settleableAmount)}
                </p>
              </div>
            </motion.div>
          </>
        ) : (
          <>
            {Array(4).fill(0).map((_, i) => (
              <motion.div
                key={i}
                variants={cardVariants}
                initial="hidden"
                animate="show"
                className="bg-white rounded-lg border border-neutral-200 shadow-sm overflow-hidden transition-all hover:shadow-md"
              >
                <div class="p-6">
                  <h3 class="text-sm font-medium text-neutral-600 mb-2">بارگذاری...</h3>
                  <p class="text-2xl font-bold text-neutral-900">---</p>
                </div>
              </motion.div>
            ))}
          </>
        )}

        {/* Financial Trend Chart */}
        <motion.div
          variants={cardVariants}
          initial="hidden"
          animate="show"
          className="col-span-2 md:col-span-4 bg-white rounded-lg border border-neutral-200 shadow-sm overflow-hidden transition-all hover:shadow-md"
        >
          <div class="p-6">
            <h3 class="text-sm font-medium text-neutral-600 mb-4">روند مالی ماهانه</h3>
            {summaryData && summaryData.monthlyTrends ? (
              <div class="h-48 relative">
                <svg class="w-full h-full" viewBox="0 0 100 60" preserveAspectRatio="none">
                  {/* Axes */}
                  <line x1="10" y1="50" x2="90" y2="50" stroke="neutral-200" strokeWidth="1" />
                  <line x1="10" y1="10" x2="10" y2="50" stroke="neutral-200" strokeWidth="1" />

                  {/* Line Chart */}
                  <path
                    d={generateChartPath(summaryData.monthlyTrends, 10, 50, 80, 40)}
                    fill="none"
                    stroke="primary"
                    strokeWidth="2"
                  >
                    <animateTransform
                      attributeName="transform"
                      type="scale"
                      from="0"
                      to="1"
                      begin="0s"
                      dur="0.8s"
                      fill="freeze"
                    />
                  </path>

                  {/* Points */}
                  {summaryData.monthlyTrends.map((point, index) => {
                    const x = 10 + (index * (80 / (summaryData.monthlyTrends.length - 1 || 1)));
                    const y = 50 - ((point.amount - minAmount) / (maxAmount - minAmount || 1) * 40);
                    return (
                      <circle
                        key={index}
                        cx={x}
                        cy={y}
                        r="3"
                        fill="primary"
                      >
                        <animateTransform
                          attributeName="transform"
                          type="scale"
                          from="0"
                          to="1"
                          begin={index * 0.1}s
                          dur="0.3s"
                          fill="freeze"
                        />
                      </circle>
                    );
                  })}
                </svg>
              </div>
            ) : (
              <p class="text-neutral-500 text-center py-8">داده‌ای برای نمایش وجود ندارد</p>
            )}
          </div>
        </motion.div>

        {/* Action Buttons */}
        <motion.div
          variants={cardVariants}
          initial="hidden"
          animate="show"
          className="col-span-2 md:col-span-4 bg-white rounded-lg border border-neutral-200 shadow-sm overflow-hidden transition-all hover:shadow-md flex flex-col items-center gap-4 p-6"
        >
          <button
            onClick={handleSettlementRequest}
            disabled={settlementLoading}
            className="inline-flex items-center justify-center gap-2 bg-primary text-white font-medium text-base px-6 py-2.5 rounded-lg shadow-sm hover:bg-primary-dark transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {settlementLoading ? (
              <>
                <svg class="h-4 w-4 animate-spin" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9h0m-1.416 0A8.001 8.001 0 0114.024 11M11 9v5h.582m15.356 2A8.001 8.001 0 0119.418 9h0m-1.416 0A8.001 8.001 0 0014.582 9h0m-1.416 0A8.001 8.001 0 019.024 11M15 9h4m-4 4h4m4-4H9m4 4H9" />
                </svg>
                <span>در حال پردازش...</span>
              </>
            ) : (
              'درخواست تسویه'
            )}
          </button>

          <button
            onClick={handleCSVExport}
            disabled={csvLoading}
            className="inline-flex items-center justify-center gap-2 bg-white text-primary border border-primary font-medium text-base px-6 py-2.5 rounded-lg shadow-sm hover:bg-neutral-50 transition-all focus:outline-none focus:ring-2 focus:ring-primary"
          >
            {csvLoading ? (
              <>
                <svg class="h-4 w-4 animate-spin text-primary" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9h0m-1.416 0A8.001 8.001 0 0114.024 11M11 9h.582m15.356 2A8.001 8.001 0 0119.418 9h0m-1.416 0A8.001 8.001 0 0014.582 9h0m-1.416 0A8.001 8.001 0 019.024 11M15 9h4m-4 4h4m4-4H9m4 4H9" />
                </svg>
                <span>در حال آماده‌سازی...</span>
              </>
            ) : (
              'خروجی CSV'
            )}
          </button>
        </motion.div>
      </div>
    </div>
  </main>

  {/* Settlement Request Modal */}
  {showSettlementModal && (
    <div class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <motion.div
        variants={modalVariants}
        initial="hidden"
        animate="show"
        className="w-full max-w-md bg-white rounded-xl shadow-lg p-6"
      >
        <h3 class="text-xl font-semibold text-neutral-900 mb-4">تایید درخواست تسویه</h3>
        <p class="text-neutral-600 mb-6">
          آیا از درخواست تسویه مبلغ قابل تسویه ({formatCurrency(
            settlementAmount
          )}) اطمینان دارید؟ این iş پس از تأیید قابل بازگشت نیست.
        </p>
        <div class="flex justify-end gap-3">
          <button
            onClose
            className="inline-flex items-center justify-center gap-2 bg-transparent text-neutral-600 font-medium text-base px-4 py-2.5 rounded-lg hover:bg-neutral-100 transition-all focus:outline-none focus:ring-2 focus:ring-neutral-400"
          >
            انصراف
          </button>
          <button
            onClick={handleConfirmSettlement}
            disabled={confirmLoading}
            className="inline-flex items-center justify-center gap-2 bg-primary text-white font-medium text-base px-6 py-2.5 rounded-lg shadow-sm hover:bg-primary-dark transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {confirmLoading ? (
              <>
                <svg class="h-4 w-4 animate-spin" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9h0m-1.416 0A8.001 8.001 0 0114.024 11M11 9h.582m15.356 2A8.001 8.001 0 0119.418 9h0m-1.416 0A8.001 8.001 0 0014.582 9h0m-1.416 0A8.001 8.001 0 019.024 11M15 9h4m-4 4h4m4-4H9m4 4H9" />
                </svg>
                <span>در حال تأیید...</span>
              </>
            ) : (
              'تایید و ارسال'
            )}
          </button>
        </div>
      </motion.div>
    </div>
  )}

  {/* Toast Notification */}
  {toastMessage && (
    <div class="fixed bottom-4 right-4 z-50">
      <motion.div
        variants={toastVariants}
        initial="hidden"
        animate="show"
        exit="hide"
        className={`flex items-center w-64 px-4 py-3 rounded-lg shadow-lg ${
          toastType === 'success'
            ? 'bg-success/90 text-success border border-success/20'
            : 'bg-danger/90 text-danger border border-danger/20'
        }`}
      >
        <svg class="h-5 w-5 flex-shrink-0" viewBox="0 0 24 24" stroke="currentColor">
          {toastType === 'success' ? (
            <path strokeLinecap="round" strokeLinejoin="round" d="M9 12l2 2 4-4M7.5 8.25l9 9" />
          ) : (
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
          )}
        </svg>
        <span class="ml-3">{toastMessage}</span>
      </motion.div>
    </div>
  )}
</div>

